    public EventHub(String locationName) {
        this.locationName = locationName;
    }

    // Member Inner Class
    public class AlertLogger {
        public void log(String status) {
            System.out.println(status + ": Alert logged at " + locationName);
        }
    }

    public void dispatchAlert(int severity) {
        // Local Inner Class
        ________________ {
            void process() {
                AlertLogger logger = new AlertLogger();
                if (severity > 5) {
                    logger.log("CRITICAL");
                } else {
                    logger.log("NORMAL");
                }
            }
        }

        _________________________________;
        handler.process();
    }
}

public class Main {
    public static void main(String[] args) {
